python3 -c '
from two_bucket import measure
import math

impossible_cases = []
total_tested = 0

for b1 in range(1, 21):
    for b2 in range(1, 21):
        g_gcd = math.gcd(b1, b2)
        for goal in range(1, max(b1, b2) + 1):
            if goal % g_gcd != 0:
                continue
            for start in ("one", "two"):
                total_tested += 1
                try:
                    moves, win_bucket, other = measure(b1, b2, goal, start)
                    assert moves >= 1
                    assert win_bucket in ("one", "two")
                    assert other >= 0
                    if win_bucket == "one":
                        assert b1 >= goal
                        assert other <= b2
                    else:
                        assert b2 >= goal
                        assert other <= b1
                except ValueError:
                    impossible_cases.append((b1, b2, goal, start))

print(f"Tested {total_tested} valid (b1, b2, goal, start) tuples.")
print(f"Impossible cases found: {len(impossible_cases)}")
if impossible_cases:
    print("Examples of impossible:", impossible_cases[:10])
'
